    private fun filled(name: String, w: Float, h: Float, d: String): ImageVector =
        ImageVector.Builder(
            name = name,
            defaultWidth = w.dp,
            defaultHeight = h.dp,
            viewportWidth = w,
            viewportHeight = h,
        ).addPath(
            pathData = PathParser().parsePathString(d).toNodes(),
            fill = SolidColor(Color.Black),
        ).build()

    private fun stroked(name: String, d: String, strokeWidth: Float): ImageVector =
        ImageVector.Builder(
            name = name,
            defaultWidth = 24.dp,
            defaultHeight = 24.dp,
            viewportWidth = 24f,
            viewportHeight = 24f,
        ).addPath(
            pathData = PathParser().parsePathString(d).toNodes(),
            fill = null,
            stroke = SolidColor(Color.Black),
            strokeLineWidth = strokeWidth,
            strokeLineCap = StrokeCap.Round,
            strokeLineJoin = StrokeJoin.Round,
        ).build()

